      var labelCell = '<td class="lab">' + esc(r.label) + '</td>';
      if (hasGroupCol) {
        var prev = nt.rows[rix - 1], same = prev && prev.type === 'row' && prev.label === r.label;
        if (same) labelCell = '';
        else { var n = 1; while (nt.rows[rix + n] && nt.rows[rix + n].type === 'row' && nt.rows[rix + n].label === r.label) n++; labelCell = '<td class="lab" rowspan="' + n + '">' + esc(r.label) + '</td>'; }
        labelCell += '<td class="grp">' + esc(r.group || '') + '</td>';
      }
      var b = 'd:' + paneKey + ':' + tblKey + ':' + r.idx, chId = 'ch-' + paneKey + '-' + tblKey + '-' + r.idx;
      var isChart = hasNatCols && !opts.plain;
