      if (nt.nat3) h += r.navg ? avgHtml(r.navg, b + ':n3y') : '<td>—</td>';
      if (withGap) { var gi = -1; r.cells.forEach(function (c, i) { if (c && c.gap && c.gap.num != null) gi = i; }); h += '<td class="gap">' + (gi !== -1 ? esc(r.cells[gi].gap.disp + (r.cells[gi].trend ? ' (' + r.cells[gi].trend + ')' : '')) : '—') + '</td>'; }
