        var series = [{ name: 'School', cls: 'school', vals: r.cells.map(function (c) { return c ? c.num : null; }) }, { name: 'National', cls: 'national', vals: r.cells.map(function (c) { return c && !c.nat.est ? c.nat.num : null; }) }];
